templates._includes/blocks.html:
{% for block in include.sections %}
<section class="content-block block-{{ block.type | escape }}"{% if block.anchor and block.anchor != '' %} id="{{ block.anchor | escape }}"{% endif %}>
  {% if block.heading and block.heading != '' %}<h2>{{ block.heading | escape }}</h2>{% endif %}
  {% case block.type %}
  {% when 'text' %}<div class="prose">{{ block.body | markdownify }}</div>
  {% when 'image' %}{% if block.image and block.image != '' %}<figure><button class="image-trigger" type="button" data-image="{{ block.image | relative_url }}" data-caption="{{ block.caption | escape }}" aria-label="Enlarge {{ block.alt | default: page.title | escape }}"><img src="{{ block.image | relative_url }}" alt="{{ block.alt | default: page.title | escape }}" loading="lazy" decoding="async"></button>{% if block.caption != '' or block.credit != '' %}<figcaption>{{ block.caption | escape }}{% if block.credit and block.credit != '' %} <span>© {{ block.credit | escape | replace: 'Teng Teng', '<strong>Teng Teng</strong>' }}</span>{% endif %}</figcaption>{% endif %}</figure>{% endif %}
  {% when 'gallery' %}<div class="gallery gallery-{{ block.columns | default: 'two' }}"{% if block.image_ratios.size == 2 or page.gallery_width_percent %} style="{% if page.gallery_width_percent %}width:{{ page.gallery_width_percent | escape }}%;margin-inline:{% if page.image_alignment == 'left' %}0{% else %}auto{% endif %};{% endif %}{% if block.image_ratios.size == 2 %}grid-template-columns:minmax(0,{{ block.image_ratios[0] }}fr) minmax(0,{{ block.image_ratios[1] }}fr){% endif %}"{% endif %}>{% for image in block.images %}<figure><button class="image-trigger" type="button" data-image="{{ image | relative_url }}" data-caption="{{ block.caption | escape }}" aria-label="Enlarge {{ page.title | escape }} image {{ forloop.index }}"><img src="{{ image | relative_url }}" alt="{{ page.title | escape }} — {{ block.heading | default: 'project image' | escape }} {{ forloop.index }}" loading="lazy" decoding="async"></button></figure>{% endfor %}</div>{% if block.caption and block.caption != '' %}<p class="caption">{{ block.caption | escape }}</p>{% endif %}
  {% when 'video' %}{% include project-video.html block=block %}
  {% when 'media-row' %}
    <div class="media-row{% if block.equal_height %} media-row-equal-height{% endif %}" data-items="{{ block.items.size }}">
      {% for item in block.items %}
      <figure style="--media-ratio:{{ item.ratio | default: 1 | escape }}">
        {% if item.type == 'video' %}{% include project-video.html block=item hide_caption=true %}
        {% else %}<button class="image-trigger" type="button" data-image="{{ item.image | relative_url }}" data-caption="{{ item.alt | escape }}" aria-label="Enlarge {{ item.alt | default: page.title | escape }}"><img src="{{ item.image | relative_url }}" alt="{{ item.alt | default: page.title | escape }}"{% if item.width_percent %} style="width:{{ item.width_percent | escape }}%;margin-inline:auto"{% endif %} loading="lazy" decoding="async"></button>{% endif %}
      </figure>
      {% endfor %}
    </div>
    {% if block.caption and block.caption != '' %}<p class="caption">{{ block.caption | escape }}</p>{% endif %}
  {% when 'video-gallery' %}
    <div class="gallery gallery-two"{% if block.width_percent %} style="width:calc({{ block.width_percent | escape }}% + 15px);max-width:100%"{% endif %}>
      {% for clip in block.videos %}<div>{% include project-video.html block=clip hide_caption=true %}</div>{% endfor %}
    </div>
    {% if block.caption and block.caption != '' %}<p class="caption">{{ block.caption | escape }}</p>{% endif %}
  {% when 'quote' %}<blockquote>{{ block.text | escape }}{% if block.attribution %}<cite>{{ block.attribution | escape }}</cite>{% endif %}</blockquote>
  {% when 'links' %}<ul class="resource-list">{% for item in block.items %}<li><a href="{{ item.url | escape }}" target="_blank" rel="noopener">{{ item.title | escape }} ↗</a></li>{% endfor %}</ul>
  {% endcase %}
</section>
{% endfor %}

templates._includes/project-brief.html:
{% if page.research_question or page.role_summary or page.evidence_summary %}
<dl class="project-brief" aria-label="Project at a glance">
  {% if page.research_question %}<div><dt>{{ page.question_label | default: 'Question' | escape }}</dt><dd>{{ page.research_question | escape }}</dd></div>{% endif %}
  {% assign brief_role = page.role_summary | default: page.role %}{% if brief_role %}<div><dt>My role</dt><dd>{{ brief_role | escape }}</dd></div>{% endif %}
</dl>
{% endif %}

templates._includes/project-card.html:
{% assign p = include.project %}
<article class="project-card" data-category="{{ p.category | escape }}" data-search="{{ p.title | escape }} {{ p.summary | escape }} {{ p.tags | join: ' ' | escape }} {{ p.year | escape }} {{ p.project_type | escape }} {{ p.project_stage | escape }} {{ p.location | escape }}">
  <a href="{{ p.url | relative_url }}" class="project-link">
    {% if p.cover and p.cover != '' %}{% include project-thumbnail.html project=p %}
    {% else %}<div class="project-image text-cover"><span>{{ p.category | capitalize }}</span><strong>{{ p.title | escape }}</strong></div>{% endif %}
    <p class="eyebrow">{{ p.category | capitalize }}{% if p.year and include.hide_year != true %}<span>{{ p.year | escape }}</span>{% endif %}</p>
    <h3>{{ p.card_title | default: p.title | escape }}</h3>
    {% if include.relation %}<p class="card-relation">{{ include.relation | escape }}</p>{% endif %}
    {% if include.compact != true and p.summary and p.summary != p.title %}<p class="card-summary">{{ p.summary | escape }}</p>{% endif %}
  </a>
</article>

templates._includes/project-method.html:
{% if page.contribution or page.method_steps.size > 0 %}
<section id="project-method" class="project-method" aria-label="Project methods">
  {% if page.contribution %}<div class="method-intro"><h2>Method</h2><p>{{ page.contribution | escape }}</p></div>{% endif %}
  {% if page.method_steps.size > 0 %}<ol class="method-steps">{% for step in page.method_steps %}<li><span class="eyebrow">0{{ forloop.index }}</span><h3>{{ step.title | escape }}</h3><p>{{ step.text | escape }}</p></li>{% endfor %}</ol>{% endif %}
</section>
{% endif %}

templates._includes/project-reading-path.html:
{% if page.reading_path.size > 0 %}
<nav class="project-reading-path" aria-label="Project reading order">
  <span>Read the project</span><ol>{% for item in page.reading_path %}<li><a href="#{{ item.target | escape }}">{{ item.title | escape }}</a></li>{% endfor %}</ol>
</nav>
{% endif %}

templates._includes/project-thumbnail.html:
