    {% elsif video_url contains 'vimeo.com/' %}{% assign video_id = video_url | split: 'vimeo.com/' | last | split: '?' | first %}<div class="video-frame"><iframe src="https://player.vimeo.com/video/{{ video_id | escape }}?autoplay=1&amp;muted=1&amp;loop=1&amp;autopause=0&amp;playsinline=1" title="{{ video_block.heading | default: 'Project video' | escape }}" loading="eager" allow="autoplay; encrypted-media; fullscreen; picture-in-picture" allowfullscreen></iframe></div>
