templates._includes/publication-projects.html:
{% assign research_projects = site.projects | where: 'published', true | where: 'category', 'research' %}
{% for research_project in research_projects %}
  {% for related_publication in research_project.related_publications %}
    {% if related_publication.publication_id == include.publication_id %}
      <a href="{{ research_project.url | relative_url }}">Project: {{ research_project.card_title | default: research_project.title | escape }} →</a>
      {% break %}
    {% endif %}
  {% endfor %}
{% endfor %}

templates._includes/related-projects.html:
{% comment %}Only authored connections qualify. Category, recency and generic keywords are not evidence of a relationship.{% endcomment %}
{% assign rp_projects = site.projects | where: 'published', true %}
{% assign rp_count = 0 %}
{% capture rp_cards %}
{% if page.related_connections.size > 0 %}
  {% for connection in page.related_connections %}
    {% assign project = rp_projects | where: 'url', connection.url | first %}
    {% if project and project.url != page.url and rp_count < 3 %}
      {% include project-card.html project=project compact=true relation=connection.reason %}
      {% assign rp_count = rp_count | plus: 1 %}
    {% endif %}
  {% endfor %}
{% else %}
  {% for project_url in page.related_projects %}
    {% assign project = rp_projects | where: 'url', project_url | first %}
    {% if project and project.url != page.url and rp_count < 3 %}
      {% include project-card.html project=project compact=true %}
      {% assign rp_count = rp_count | plus: 1 %}
    {% endif %}
  {% endfor %}
{% endif %}
{% endcapture %}
{% if rp_count > 0 %}
<section class="section related-projects" aria-labelledby="related-projects-heading">
  <div class="section-heading"><h2 id="related-projects-heading">Related projects</h2><a class="text-link" href="{{ '/gallery/' | relative_url }}">All projects →</a></div>
  <div class="project-grid">{{ rp_cards }}</div>
</section>
{% endif %}

templates._layouts/institution.html:
---
layout: default
---
{% assign institution = site.data.institutions[page.institution_key] %}
{% assign projects = site.projects | where: 'published', true | sort: 'year' | reverse %}
{% assign project_count = 0 %}
{% capture project_cards %}
  {% for project in projects %}
    {% assign belongs = false %}
    {% if institution.match and project.institution contains institution.match %}{% assign belongs = true %}{% endif %}
    {% if institution.projects contains project.url %}{% assign belongs = true %}{% endif %}
    {% if belongs %}
      {% assign project_count = project_count | plus: 1 %}
      {% include project-card.html project=project compact=true hide_year=true %}
    {% endif %}
  {% endfor %}
{% endcapture %}
<div class="page-top"><a class="back-link" href="{{ '/about/' | relative_url }}">← About Teng</a></div>
<header class="page-heading">
  <p class="eyebrow">{% if institution.kind == 'service' %}Academic service{% else %}Work by institution{% endif %}</p>
  <h1>{{ institution.name | escape }}</h1>
  {% if institution.role %}<p class="lead">{{ institution.role | escape }}</p>{% endif %}
  {% if institution.description %}<p class="caption">{{ institution.description | escape }}</p>{% endif %}
</header>
{% if project_count > 0 %}
<section class="catalog-group" aria-label="{% if institution.kind == 'service' %}Related projects{% else %}Projects at {{ institution.name | escape }}{% endif %}">
  <p class="result-count">{{ project_count }} {% if project_count == 1 %}project{% else %}projects{% endif %}</p>
  <div class="project-grid">{{ project_cards }}</div>
</section>
{% else %}
<p class="caption">{% if institution.kind == 'service' %}No related project pages are currently included in this portfolio.{% else %}Projects from this institution have not yet been added to this portfolio.{% endif %}</p>
{% endif %}

templates._layouts/project.html:
---
layout: default
---
<div class="page-top"><a class="back-link" href="{{ page.category | prepend: '/' | append: '/' | relative_url }}">← {{ page.category | capitalize }}</a><p class="eyebrow">{{ page.year | escape }}</p></div>
<header class="project-heading" data-project-page="{{ page.url | relative_url }}"><h1>{{ page.title | escape }}</h1>{% if page.summary and page.summary != '' %}<p class="lead">{{ page.summary | escape }}</p>{% endif %}{% if page.primary_link and page.interactive_map != true %}<div class="actions"><a class="button" href="{{ page.primary_link.url | escape }}" target="_blank" rel="noopener">{{ page.primary_link.title | escape }} ↗</a></div>{% endif %}</header>
{% include project-brief.html %}
{% include project-reading-path.html %}
{% if page.structure_lab %}{% include structure-lab.html %}{% endif %}
{% if page.interactive_map %}{% include chinatown-map.html %}{% elsif page.hero_gallery and page.hero_gallery.size > 0 %}
<section class="project-hero-carousel" data-hero-carousel data-carousel-fit="{{ page.hero_gallery_fit | default: 'cover' | escape }}" tabindex="0" aria-label="{{ page.title | escape }} project photography">
  <div class="hero-carousel-viewport">
    <div class="hero-carousel-track" data-carousel-track>
      {% for item in page.hero_gallery %}
      <figure class="hero-carousel-slide" data-carousel-slide data-carousel-duration-ms="{{ item.duration_ms | default: 2000 | escape }}" aria-hidden="{% if forloop.first %}false{% else %}true{% endif %}">
        <button class="image-trigger" type="button" data-image="{{ item.image | relative_url }}" data-caption="{{ item.caption | escape }}" aria-label="Enlarge {{ item.alt | default: page.title | escape }}">
          <img src="{{ item.image | relative_url }}" alt="{{ item.alt | default: page.title | escape }}" loading="eager" {% if forloop.first %}fetchpriority="high"{% endif %} decoding="async">
        </button>
        {% if item.caption and item.caption != '' %}<figcaption>{{ item.caption | escape }}</figcaption>{% endif %}
      </figure>
      {% endfor %}
    </div>
    <button class="hero-carousel-nav hero-carousel-prev" type="button" data-carousel-prev aria-label="Previous photograph">←</button>
    <button class="hero-carousel-nav hero-carousel-next" type="button" data-carousel-next aria-label="Next photograph">→</button>
  </div>
  <div class="hero-carousel-meta">
    <div class="hero-carousel-dots" aria-label="Select photograph">
      {% for item in page.hero_gallery %}<button type="button" data-carousel-dot="{{ forloop.index0 }}" aria-label="Show photograph {{ forloop.index }}"{% if forloop.first %} aria-current="true"{% endif %}></button>{% endfor %}
    </div>
    <div class="hero-carousel-controls"><button class="hero-carousel-toggle" type="button" data-carousel-toggle aria-label="Pause slideshow" aria-pressed="false">Pause</button><span class="hero-carousel-status" data-carousel-status>1 / {{ page.hero_gallery.size }}</span></div>
  </div>
</section>
{% elsif page.cover and page.cover != '' and page.cover_preview_only != true %}<figure class="project-hero"{% if page.cover_width_percent %} style="width:{{ page.cover_width_percent | escape }}%;margin-inline:{% if page.image_alignment == 'left' %}0{% else %}auto{% endif %}"{% endif %}><button class="image-trigger" type="button" data-image="{{ page.cover | relative_url }}" aria-label="Enlarge {{ page.cover_alt | default: page.title | escape }}"><img src="{{ page.cover | relative_url }}" alt="{{ page.cover_alt | default: page.title | escape }}" fetchpriority="high" decoding="async"></button>{% if page.cover_caption %}<figcaption>{{ page.cover_caption | escape }}</figcaption>{% endif %}</figure>{% endif %}
{% if page.opening_sections.size > 0 %}<div class="project-opening" aria-label="Completed project and film">{% include blocks.html sections=page.opening_sections %}</div>{% endif %}
<div class="project-layout">
  <article class="project-body">
    {% if page.evidence_summary %}<p class="project-evidence-summary">{{ page.evidence_summary | escape }}{% if page.evidence_target %} <a href="#{{ page.evidence_target | escape }}">View evidence ↓</a>{% endif %}</p>{% endif %}
    {% assign evidence_count = page.evidence_first | default: 0 %}
    {% if evidence_count > 0 %}{% assign first_sections = page.sections | slice: 0, evidence_count %}<div id="project-evidence">{% include blocks.html sections=first_sections %}</div>{% endif %}
    <div class="prose project-context">{{ content }}</div>
    {% include project-method.html %}
    {% if evidence_count > 0 %}{% assign remaining_sections = page.sections | slice: evidence_count, 1000 %}{% include blocks.html sections=remaining_sections %}{% else %}<div id="project-evidence">{% include blocks.html sections=page.sections %}</div>{% endif %}
    {% if page.evidence %}<section class="evidence-note" id="project-scope"><h2>{{ page.evidence_label | default: "Evidence & scope" | escape }}</h2><p>{{ page.evidence | escape }}</p></section>{% endif %}
    {% if page.category == 'research' %}{% include research-publications.html %}{% endif %}
  </article>
  <aside id="project-details" class="project-details" aria-label="Project details">
    <dl><dt>Category</dt><dd>{{ page.category | capitalize }}</dd>{% if page.year and page.year != '' %}<dt>Year</dt><dd>{{ page.year | escape }}</dd>{% endif %}{% if page.project_type and page.project_type != '' %}<dt>Project type</dt><dd>{{ page.project_type | escape }}</dd>{% endif %}{% if page.project_stage and page.project_stage != '' %}<dt>Stage</dt><dd>{{ page.project_stage | escape }}</dd>{% endif %}{% if page.role and page.role != '' %}<dt>My role</dt><dd>{{ page.role | escape }}</dd>{% endif %}{% if page.institution and page.institution != '' %}<dt>Institution</dt><dd>{{ page.institution | escape }}</dd>{% endif %}{% if page.location and page.location != '' %}<dt>Location</dt><dd>{{ page.location | escape }}</dd>{% endif %}</dl>
    {% if page.contributions.size > 0 %}<h2>My contribution</h2><ul>{% for item in page.contributions %}<li>{{ item | escape }}</li>{% endfor %}</ul>{% endif %}
    {% if page.tags.size > 0 %}<div class="tag-list">{% for tag in page.tags %}<span>{{ tag | escape }}</span>{% endfor %}</div>{% endif %}
    {% if page.credits.size > 0 %}<h2>Credits</h2><ul>{% for item in page.credits %}<li>{{ item | escape }}</li>{% endfor %}</ul>{% endif %}
    {% if page.team.size > 0 %}<h2>Team</h2><ul>{% for item in page.team %}<li>{{ item | escape }}</li>{% endfor %}</ul>{% endif %}
    {% if page.acknowledgements and page.acknowledgements != '' %}<h2>Acknowledgements</h2><p>{{ page.acknowledgements | escape }}</p>{% endif %}
    {% if page.awards.size > 0 %}<h2>Awards</h2><ul>{% for item in page.awards %}<li><a href="{{ item.url | escape }}" target="_blank" rel="noopener">{{ item.title | escape }} ↗</a></li>{% endfor %}</ul>{% endif %}
    {% if page.category != 'research' and page.related_publications.size > 0 %}<h2>Related publications</h2><ul>{% for item in page.related_publications %}<li><a href="{{ item.url | escape }}" target="_blank" rel="noopener">{{ item.title | escape }} ↗</a></li>{% endfor %}</ul>{% endif %}
    {% if page.links.size > 0 %}<h2>Resources</h2><ul>{% for item in page.links %}<li><a href="{{ item.url | escape }}" target="_blank" rel="noopener">{{ item.title | escape }} ↗</a></li>{% endfor %}</ul>{% endif %}
  </aside>
</div>
{% include related-projects.html %}

