pages.index.html:
---
title: Computational Design through Materiality
description: Materiality as an active dimension of computational design. Research, teaching, and architectural practice by Teng Teng.
---
<style>
.home-index-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 24px;
  padding: 32px 0 24px;
}
.home-index-heading h1 { margin: 0; }
.home-index-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 20px; font-size: 13px; }
.home-sort-control { display: flex; align-items: center; gap: 8px; margin: 0; }
.home-sort-control span { color: var(--muted); }
.home-sort-control select {
  width: auto;
  padding: 5px 24px 5px 8px;
  border: 1px solid var(--control-line);
  border-radius: 2px;
  background-color: var(--paper);
  color: var(--ink);
  font: inherit;
}
.home-sort-control select:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.home-shuffle {
  appearance: none;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 3px 0;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}
.home-shuffle:hover { border-color: var(--ink); }
.home-shuffle:focus-visible { outline: 2px solid var(--accent); outline-offset: 5px; }
 .home-focus { max-width: 880px; margin: -4px 0 28px; font-size: var(--text-body); line-height: 1.6; color: var(--muted); }
.home-catalog .project-card h2 {
  font: var(--text-card)/1.35 var(--serif);
  letter-spacing: -.015em;
  margin: 0;
}
.home-catalog .eyebrow { margin-bottom: 8px; }
.home-grid-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 560px) {
  .home-index-actions { gap: 18px; font-size: 12px; }
}
</style>
<header class="page-heading home-index-heading">
  <h1>{{ site.data.site.home_title | escape }}</h1>
  <div class="home-index-actions">
    <label class="home-sort-control" id="home-sort-control" hidden>
      <span>Sort</span>
      <select id="home-sort" aria-label="Explore or sort all projects" aria-controls="home-projects">
        <option value="random">Explore</option>
        <option value="date">Newest first</option>
        <option value="type">Project type</option>
      </select>
    </label>
    <button class="home-shuffle" id="home-shuffle" type="button" aria-controls="home-projects" hidden>Discover more ↻</button>
    <a class="text-link" href="{{ '/gallery/' | relative_url }}">All projects →</a>
  </div>
</header>
<p class="home-focus">{{ site.data.site.home_focus | escape }}</p>
{% assign published_projects = site.projects | where: 'published', true %}
<div class="project-grid home-catalog" id="home-projects">
  {% for project in published_projects %}
    {% assign core_order = 0 %}
    {% for core_url in site.data.home.core_projects %}
      {% if project.url == core_url %}{% assign core_order = forloop.index %}{% endif %}
    {% endfor %}
    {% assign home_weight = 1 %}
    {% assign home_tags = project.tags | join: ' ' | downcase %}
    {% assign home_type = project.project_type | downcase %}
    {% assign home_topics = project.title | append: ' ' | append: project.summary | append: ' ' | append: home_type | append: ' ' | append: home_tags | downcase %}
    {% if project.category == 'research' %}
      {% if project.research_areas contains 'material-computation' or home_topics contains 'fabrication' or home_topics contains 'material' or home_topics contains 'printing' %}{% assign home_weight = site.data.home.priority_weight %}{% endif %}
    {% elsif project.category == 'design' %}
      {% if project.built == true or site.data.home.built_design_projects contains project.url %}{% assign home_weight = site.data.home.priority_weight %}{% endif %}
    {% elsif project.category == 'teaching' %}
      {% if home_type contains 'design studio' or home_type contains 'thesis supervision' or home_tags contains 'design-build' %}{% assign home_weight = site.data.home.priority_weight %}{% endif %}
    {% endif %}
    <article class="project-card" data-project-id="{{ project.url | escape }}" data-core-order="{{ core_order }}" data-year="{{ project.year | escape }}" data-category="{{ project.category | escape }}" data-title="{{ project.card_title | default: project.title | escape }}" data-weight="{{ home_weight }}">
      <a href="{{ project.url | relative_url }}" class="project-link">
        {% if project.cover and project.cover != '' %}
          {% include project-thumbnail.html project=project %}
        {% else %}
          <div class="project-image text-cover" aria-hidden="true"><span>{{ project.category | capitalize }}</span><strong>{{ project.card_title | default: project.title | escape }}</strong></div>
        {% endif %}
        <p class="eyebrow">{{ project.category | capitalize }}{% if project.year and project.year != '' %}<span>{{ project.year | escape }}</span>{% endif %}</p>
        <h2>{{ project.card_title | default: project.title | escape }}</h2>
      </a>
    </article>
  {% endfor %}
</div>
<p class="home-grid-status" id="home-grid-status" role="status" aria-live="polite"></p>
<script>
(() => {
  'use strict';
  const grid = document.getElementById('home-projects');
  const button = document.getElementById('home-shuffle');
  const sort = document.getElementById('home-sort');
  const sortControl = document.getElementById('home-sort-control');
  const status = document.getElementById('home-grid-status');
  // One canonical URL per project, including work listed in several catalogues.
  const pool = Array.from(new Map(Array.from(grid.children).map(card => [card.dataset.projectId, card])).values());
  const limit = 16;
  const core = pool.filter(card => Number(card.dataset.coreOrder) > 0)
    .sort((a, b) => Number(a.dataset.coreOrder) - Number(b.dataset.coreOrder)).slice(0, 4);
  const rotatingPool = pool.filter(card => !core.includes(card));
  const typeOrder = { research: 0, teaching: 1, design: 2 };
  const year = card => Math.max(0, ...(card.dataset.year.match(/\b\d{4}\b/g) || []).map(Number));
  const byDate = (a, b) => year(b) - year(a) || a.dataset.title.localeCompare(b.dataset.title);
  let selection = [];
  let previousExplore = new Set();

  function weightedOrder(cards) {
    return cards.map(card => ({ card, key: -Math.log(1 - Math.random()) / (Number(card.dataset.weight) || 1) }))
      .sort((a, b) => a.key - b.key)
      .map(entry => entry.card);
  }

  function freshFirst(cards) {
    // New identities take precedence over weights or reshuffling the same cards.
    return weightedOrder(cards.filter(card => !previousExplore.has(card.dataset.projectId)))
      .concat(weightedOrder(cards.filter(card => previousExplore.has(card.dataset.projectId))));
  }

  function randomSelection() {
    // Keep four additional projects from each discipline; core projects use no quota.
    const groups = ['research', 'design', 'teaching'].map(category => ({
      category,
      cards: freshFirst(rotatingPool.filter(card => card.dataset.category === category)).slice(0, 4)
    }));
    const cards = [];
    let previousCategory = core.at(-1)?.dataset.category;
    while (groups.some(group => group.cards.length)) {
      // Interleave disciplines so printed research samples are separated by other work.
      const round = [...groups];
      for (let i = round.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [round[i], round[j]] = [round[j], round[i]];
      }
      const first = round.findIndex(group => group.cards.length && group.category !== previousCategory);
      if (first > 0) [round[0], round[first]] = [round[first], round[0]];
      for (const group of round) {
        if (!group.cards.length) continue;
        cards.push(group.cards.shift());
        previousCategory = group.category;
      }
    }
    // If the catalogue shrinks or a core project is unpublished, fill available slots.
    const selected = new Set(cards);
    const fallback = freshFirst(rotatingPool.filter(card => !selected.has(card)));
    const rotating = cards.concat(fallback).slice(0, limit - core.length);
    previousExplore = new Set(rotating.map(card => card.dataset.projectId));
    selection = core.concat(rotating);
  }

  function render(announce = false) {
    // Ordered modes always start from the complete catalogue, not the random sample.
    if (sort.value === 'date') selection = [...pool].sort(byDate);
    if (sort.value === 'type') {
      selection = [...pool].sort((a, b) =>
        (typeOrder[a.dataset.category] ?? 3) - (typeOrder[b.dataset.category] ?? 3) || byDate(a, b));
    }
    const update = () => {
      const fragment = document.createDocumentFragment();
      selection.forEach((card, index) => {
        const image = card.querySelector('img');
        if (image) image.loading = index < 4 ? 'eager' : 'lazy';
        fragment.appendChild(card);
      });
      grid.replaceChildren(fragment);
    };
    if (announce && typeof window !== 'undefined' && window.portfolioMotion) window.portfolioMotion.reorder(grid, update);
    else update();
    // Keep each history entry's exact selection for reload and browser Back.
    try {
      history.replaceState({ ...history.state, portfolioHome: { mode: sort.value, ids: selection.map(card => card.dataset.projectId) } }, '');
    } catch { /* Storage and history may be unavailable in embedded previews. */ }
    if (announce) {
      const order = { random: core.length + ' core projects followed by a refreshed selection', date: 'newest first', type: 'grouped by project type' };
      status.textContent = selection.length + ' of ' + pool.length + ' projects, ' + order[sort.value] + '.';
    }
  }

  let saved;
  try { saved = history.state?.portfolioHome; } catch { /* Fresh visit. */ }
  sort.value = ['random', 'date', 'type'].includes(saved?.mode) ? saved.mode : 'random';
  const byId = new Map(pool.map(card => [card.dataset.projectId, card]));
  if (sort.value === 'random' && Array.isArray(saved?.ids) && saved.ids.length === Math.min(limit, pool.length) && new Set(saved.ids).size === saved.ids.length && saved.ids.every(id => byId.has(id))) {
    selection = saved.ids.map(id => byId.get(id));
    previousExplore = new Set(selection.filter(card => !core.includes(card)).map(card => card.dataset.projectId));
  } else randomSelection();
  render();
  button.hidden = false;
  sortControl.hidden = false;
  sort.addEventListener('change', () => {
    if (sort.value === 'random') randomSelection();
    render(true);
  });
  button.addEventListener('click', () => {
    sort.value = 'random';
    randomSelection();
    render(true);
  });
})();
</script>

